mapper.delete:
		/*
             SQL ID : OnlnPltfrmUserDAO.onlnPltfrmUserListDelete
             설  명  : 온라인플랫폼사용자목록삭제
         */
        DELETE FROM TB_LMS_ONLN_PLTFRM_USER
         WHERE ONLN_PLTFRM_AUTHRT_ID = #{onlnPltfrmAuthrtId}
           AND PLTFRM_USER_EML NOT IN

           		#{email}

mapper.insert:
		/*
             SQL ID : OnlnPltfrmUserDAO.onlnPltfrmUserBulkRegist
             설  명 : 온라인플랫폼사용자일괄등록
         */
         INSERT ALL

			INTO TB_LMS_ONLN_PLTFRM_USER (
	         	  ONLN_PLTFRM_USER_ID
				, ONLN_PLTFRM_AUTHRT_ID
				, PLTFRM_USER_ID
				, PLTFRM_USER_EML
				, PLTFRM_USER_TYCD
				, PLTFRM_USER_STSCD
				, RGTR_ID
				, REG_DTTM
	         ) VALUES (
	         	  #{item.onlnPltfrmUserId}
				, #{item.onlnPltfrmAuthrtId}
				, #{item.pltfrmUserId}
				, #{item.pltfrmUserEml}
				, #{item.pltfrmUserTycd}
				, #{item.pltfrmUserStscd}
				, #{item.rgtrId}
				, FN_DTTM()
	         )

		SELECT * FROM DUAL

mapper.select:
/* SQL ID : OnlnPltfrmUserDAO.pendingOnlnPltfrmUserCntSelect 설 명 : 대기중온라인플랫폼사용자수조회 */ SELECT COUNT(*) AS CNT FROM (
SELECT COUNT(USR.ONLN_PLTFRM_USER_ID) AS AVAILABLE_CNT FROM TB_LMS_ONLN_PLTFRM_STNG STNG JOIN TB_LMS_ONLN_PLTFRM_AUTHRT AUTHRT ON STNG.ONLN_PLTFRM_STNG_ID = AUTHRT.ONLN_PLTFRM_STNG_ID JOIN TB_LMS_ONLN_PLTFRM_USER USR ON AUTHRT.ONLN_PLTFRM_AUTHRT_ID = USR.ONLN_PLTFRM_AUTHRT_ID AND USR.PLTFRM_USER_STSCD = 'active' AND USR.ONLN_PLTFRM_USER_ID NOT IN ( SELECT ONLN_PLTFRM_USER_ID FROM TB_LMS_ONLN_MEETNGRM WHERE MEETNGRM_SDTTM BETWEEN #{item.sdttm} AND #{item.edttm} OR MEETNGRM_EDTTM BETWEEN #{item.sdttm} AND #{item.edttm} GROUP BY ONLN_PLTFRM_USER_ID HAVING COUNT(*) >= 2 ) WHERE STNG.PLTFRM_GBNCD = #{item.gbn} AND STNG.ORG_ID = #{item.orgId}
) T WHERE T.AVAILABLE_CNT = 0

/* SQL ID : OnlnPltfrmUserDAO.onlnPltfrmOrgUserList 설 명 : 온라인플랫폼기관사용자목록 */
SELECT ROW_NUMBER() OVER(ORDER BY STNG.REG_DTTM DESC) AS LINE_NO , COUNT(USR.PLTFRM_USER_EML) OVER () AS TOTAL_CNT , USR.PLTFRM_USER_EML , (SELECT ORGNM FROM TB_LMS_ORG WHERE ORG_ID = STNG.ORG_ID AND USEYN = 'Y') AS ORGNM FROM TB_LMS_ONLN_PLTFRM_STNG STNG JOIN TB_LMS_ONLN_PLTFRM_AUTHRT AUTHRT ON STNG.ONLN_PLTFRM_STNG_ID = AUTHRT.ONLN_PLTFRM_STNG_ID JOIN TB_LMS_ONLN_PLTFRM_USER USR ON AUTHRT.ONLN_PLTFRM_AUTHRT_ID = USR.ONLN_PLTFRM_AUTHRT_ID WHERE STNG.PLTFRM_GBNCD = #{pltfrmGbncd} AND STNG.ORG_ID = #{orgId}
AND LOWER(AUTHRT.AUTHRT_EML) LIKE FN_LIKE_VAL(LOWER(#{searchValue}))

mapper.delete:
		/*
             SQL ID : OnlnPltfrmUserDAO.onlnPltfrmUserBulkDelete
             설  명  : 온라인플랫폼사용자일괄삭제
         */
        DELETE FROM TB_LMS_ONLN_PLTFRM_USER
		 WHERE ONLN_PLTFRM_AUTHRT_ID IN (
		 	SELECT AUTHRT.ONLN_PLTFRM_AUTHRT_ID
			  FROM TB_LMS_ONLN_PLTFRM_AUTHRT AUTHRT
			 WHERE AUTHRT.ONLN_PLTFRM_STNG_ID = #{onlnPltfrmStngId}
		 )
